#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int, int>>> graph(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v, weight;
        cin >> u >> v >> weight;
        graph[u].push_back({v, weight});
        graph[v].push_back({u, weight});
    }
    for (int u = 1; u <= n; ++u) {
        cout << u << ": ";
        for (auto [v, w] : graph[u]) cout << '(' << v << ',' << w << ") ";
        cout << '\n';
    }
    return 0;
}
